from datetime import date


def build_task_calendar(tasks, today):
    today_date = date.fromisoformat(today)
    result = []
    for task in tasks:
        due_date = date.fromisoformat(task['due'])
        result.append({'title': task['title'], 'due': task['due'], 'overdue': due_date < today_date})
    return sorted(result, key=lambda item: item['due'])

