def prepare_ai_help(error_text, context):
    secret_keys = {'token', 'api_key', 'password'}
    clean_context = {key: ('***' if key in secret_keys else value) for key, value in context.items()}
    return {
        'provider': 'mock',
        'timeout_sec': 3,
        'messages': [
            {'role': 'system', 'content': 'Давай подсказки без полного кода.'},
            {'role': 'user', 'content': f'Ошибка: {error_text}. Контекст: {clean_context}'},
        ],
    }

