def build_review_log(prompt, answer):
    lowered_prompt = prompt.lower()
    lowered_answer = answer.lower()
    return {
        'has_secret': any(word in lowered_prompt for word in ['token', 'password', 'api_key']),
        'asks_full_code': 'полный код' in lowered_prompt,
        'mentions_run_check': 'запусти' in lowered_answer or 'проверь' in lowered_answer,
    }

