INSERT INTO lesson_blocks(lesson_id, block_type, title, content_md, task_id, quiz_payload, position, is_published)
SELECT lr.lesson_id, bs.block_type, bs.title, bs.content_md, tr.task_id, bs.quiz_payload, bs.position, TRUE
FROM block_seed bs
CROSS JOIN lesson_ref lr
LEFT JOIN task_ref tr ON tr.title = bs.task_title
ON CONFLICT (lesson_id, position) DO UPDATE
SET block_type = EXCLUDED.block_type,
    title = EXCLUDED.title,
    content_md = EXCLUDED.content_md,
    task_id = EXCLUDED.task_id,
    quiz_payload = EXCLUDED.quiz_payload,
    is_published = TRUE,
    updated_at = NOW();

-- m3_l29: S3 и MinIO
WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 3 AND l.position = 29
)
UPDATE lesson_blocks lb
SET is_published = FALSE,
    updated_at = NOW()
FROM lesson_ref lr
WHERE lb.lesson_id = lr.lesson_id;

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 3 AND l.position = 29
)
UPDATE tasks t
SET is_published = FALSE,
    updated_at = NOW()
FROM lesson_ref lr
WHERE t.lesson_id = lr.lesson_id;

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 3 AND l.position = 29
), task_seed(title, statement_md, starter_code, solution_code, difficulty, xp_reward, topic, language, source_policy) AS (
  VALUES
  ($m3_l29_t4_title$Upload object$m3_l29_t4_title$, $m3_l29_t4_stmt$**Коротко:** загрузи object в bucket

### Условие
Напиши `upload_text_object(client, bucket, key, text)`: вызови client.upload с bytes и content_type text/plain.

### Вход
client, bucket, object key, text

### Выход
metadata результата

### Пример
```text
notes/a.txt -> uploaded
```

### Что проверить
Запусти проверку и отдельно проверь граничный случай из условия.$m3_l29_t4_stmt$, $m3_l29_t4_starter$def upload_text_object(client, bucket, key, text):
    pass
$m3_l29_t4_starter$, $m3_l29_t4_solution$def upload_text_object(client, bucket, key, text):
    body = text.encode("utf-8")
    return client.upload(bucket=bucket, key=key, body=body, content_type="text/plain")
