INSERT INTO lesson_blocks(lesson_id, block_type, title, content_md, task_id, quiz_payload, position, is_published)
SELECT lr.lesson_id, bs.block_type, bs.title, bs.content_md, tr.task_id, bs.quiz_payload, bs.position, TRUE
FROM block_seed bs
CROSS JOIN lesson_ref lr
LEFT JOIN task_ref tr ON tr.title = bs.task_title
ON CONFLICT (lesson_id, position) DO UPDATE
SET block_type = EXCLUDED.block_type,
    title = EXCLUDED.title,
    content_md = EXCLUDED.content_md,
    task_id = EXCLUDED.task_id,
    quiz_payload = EXCLUDED.quiz_payload,
    is_published = TRUE,
    updated_at = NOW();

-- m3_l30: Сети: TCP и UDP
WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 3 AND l.position = 30
)
UPDATE lesson_blocks lb
SET is_published = FALSE,
    updated_at = NOW()
FROM lesson_ref lr
WHERE lb.lesson_id = lr.lesson_id;

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 3 AND l.position = 30
)
UPDATE tasks t
SET is_published = FALSE,
    updated_at = NOW()
FROM lesson_ref lr
WHERE t.lesson_id = lr.lesson_id;

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 3 AND l.position = 30
), task_seed(title, statement_md, starter_code, solution_code, difficulty, xp_reward, topic, language, source_policy) AS (
  VALUES
  ($m3_l30_t4_title$TCP frame length$m3_l30_t4_title$, $m3_l30_t4_stmt$**Коротко:** разбери TCP frame с длиной

### Условие
Напиши `parse_length_prefixed_frame(packet)`: первые 2 байта — длина payload.

### Вход
bytes packet

### Выход
payload bytes

### Пример
```text
0003abc -> abc
```

### Что проверить
Запусти проверку и отдельно проверь граничный случай из условия.

### Граница задачи
Этот шаг относится к уроку `Сети: TCP и UDP` и проверяет действие `TCP frame length`. Перед отправкой назови вход, действие и ожидаемый результат. Если  ?? `python_pytest` падает, сравни именно этот контракт, а не соседние темы курса.$m3_l30_t4_stmt$, $m3_l30_t4_starter$def parse_length_prefixed_frame(packet):
    pass
$m3_l30_t4_starter$, $m3_l30_t4_solution$def parse_length_prefixed_frame(packet):
    size = int.from_bytes(packet[:2], "big")
    payload = packet[2:2 + size]
    if len(payload) != size:
        raise ValueError("incomplete frame")
    return payload
