from fastapi import FastAPI

app = FastAPI()

TASKS = [{'id': 1, 'title': 'Buy milk', 'done': False}, {'id': 2, 'title': 'Read docs', 'done': True}]

@app.get('/tasks')
def list_tasks(done: bool | None = None, limit: int = 10):
    result = TASKS
    if done is not None:
        result = [task for task in result if task['done'] is done]
    return result[:limit]
