INSERT INTO lessons(module_id, title, content_md, position, is_published)
SELECT mr.module_id, ls.title, ls.content_md, ls.position, TRUE
FROM module_ref mr
CROSS JOIN lesson_seed ls
ON CONFLICT (module_id, position) DO UPDATE
SET title = EXCLUDED.title,
    content_md = EXCLUDED.content_md,
    is_published = TRUE,
    updated_at = NOW();

-- m5_l1: AI API request
WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 5 AND l.position = 1
)
UPDATE lesson_blocks lb
SET is_published = FALSE,
    updated_at = NOW()
FROM lesson_ref lr
WHERE lb.lesson_id = lr.lesson_id;

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 5 AND l.position = 1
)
UPDATE tasks t
SET is_published = FALSE,
    updated_at = NOW()
FROM lesson_ref lr
WHERE t.lesson_id = lr.lesson_id;

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 5 AND l.position = 1
), task_seed(title, statement_md, starter_code, solution_code, difficulty, xp_reward, topic, language, source_policy) AS (
  VALUES
